-- 创建者手机号归属区仅表示号码原始分配区域，不表示持有人当前所在地。
-- 印度移动号段数据来源（CC BY 4.0）：https://github.com/hstsethi/in-mob-prefix
-- 固定版本：153ba809d514e74f62a1dc88fb10f0cb1a562e0e；已移除运营商字段和归属区为空的行，并映射为中文展示名。

CREATE TABLE IF NOT EXISTS country_phone_region_prefix_mapping (
    id                         BIGINT      NOT NULL AUTO_INCREMENT COMMENT '主键',
    country_iso2               CHAR(2)     NOT NULL COMMENT '国家/地区ISO2,大写',
    normalized_national_prefix VARCHAR(15) NOT NULL COMMENT '去掉国际区号后的纯数字国内号段前缀',
    region_code                VARCHAR(32) NOT NULL COMMENT '数据源中的归属区稳定代码',
    region_name_zh             VARCHAR(96) NOT NULL COMMENT '归属区中文展示名',
    source_name                VARCHAR(128) NOT NULL COMMENT '号段数据来源',
    source_version             VARCHAR(64) NOT NULL COMMENT '号段数据版本',
    created_at                 BIGINT      NOT NULL COMMENT '创建时间(epoch毫秒)',
    updated_at                 BIGINT      NOT NULL COMMENT '更新时间(epoch毫秒)',
    PRIMARY KEY (id),
    UNIQUE KEY uq_country_phone_region_prefix (country_iso2, normalized_national_prefix),
    KEY idx_country_phone_region_code (country_iso2, region_code)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci
  COMMENT = '手机号原始号段归属区主数据（非当前所在地）';

SET @creator_phone_region_code_exists = (
    SELECT COUNT(*)
    FROM information_schema.columns
    WHERE table_schema = DATABASE()
      AND table_name = 'group_link_preview'
      AND column_name = 'creator_phone_region_code'
);
SET @creator_phone_region_code_sql = IF(
    @creator_phone_region_code_exists = 0,
    'ALTER TABLE group_link_preview ADD COLUMN creator_phone_region_code VARCHAR(32) DEFAULT NULL COMMENT ''按创建者确认手机号原始号段推断的归属区代码;非当前所在地'' AFTER creator_continent_code',
    'SELECT 1'
);
PREPARE creator_phone_region_code_stmt FROM @creator_phone_region_code_sql;
EXECUTE creator_phone_region_code_stmt;
DEALLOCATE PREPARE creator_phone_region_code_stmt;

SET @creator_phone_region_name_exists = (
    SELECT COUNT(*)
    FROM information_schema.columns
    WHERE table_schema = DATABASE()
      AND table_name = 'group_link_preview'
      AND column_name = 'creator_phone_region_name'
);
SET @creator_phone_region_name_sql = IF(
    @creator_phone_region_name_exists = 0,
    'ALTER TABLE group_link_preview ADD COLUMN creator_phone_region_name VARCHAR(96) DEFAULT NULL COMMENT ''按创建者确认手机号原始号段推断的归属区名称;非当前所在地'' AFTER creator_phone_region_code',
    'SELECT 1'
);
PREPARE creator_phone_region_name_stmt FROM @creator_phone_region_name_sql;
EXECUTE creator_phone_region_name_stmt;
DEALLOCATE PREPARE creator_phone_region_name_stmt;

