ON DUPLICATE KEY UPDATE
    region_code = VALUES(region_code),
    region_name_zh = VALUES(region_name_zh),
    source_name = VALUES(source_name),
    source_version = VALUES(source_version),
    updated_at = VALUES(updated_at);

UPDATE group_link_preview AS preview
JOIN country_phone_region_prefix_mapping AS mapping
  ON mapping.country_iso2 = 'IN'
 AND mapping.normalized_national_prefix = SUBSTRING(preview.owner_phone, 3, 4)
SET preview.creator_phone_region_code = mapping.region_code,
    preview.creator_phone_region_name = mapping.region_name_zh,
    preview.updated_at = GREATEST(preview.updated_at, 1787040000000)
WHERE preview.creator_country_iso2 = 'IN'
  AND preview.owner_phone REGEXP '^91[0-9]{10}$'
  AND (preview.creator_phone_region_code IS NULL
       OR preview.creator_phone_region_name IS NULL);
